Contract LibraryManagementSystemSystem::cancelReservation(uid:String,barcode:String): Boolean {
          definition:
          const reserves:Set(Reserve) = Reserve.allInstance()->select(res | res.ReservedUser.UserID = uid and res.ReservedCopy.Barcode = barcode)

            precondition:
          reserves->size() > 0

            postcondition:
          reserves->forAll(res:Reserve | res.IsReserveClosed = true) and reserves->forAll(res:Reserve | res.ReservedCopy.IsReserved = false) and result = true

        }
